/* Gece Devriyesi — mobil öncelikli arayüz */
:root {
  --bg: #070a11;
  --panel: rgba(18, 23, 35, .82);
  --panel-2: rgba(25, 31, 46, .72);
  --line: rgba(255, 255, 255, .09);
  --ink: #eef1f7;
  --dim: #9aa3b6;
  --dim-2: #6d778c;
  --pink: #ff5c8a;
  --pink-soft: #ffb3c9;
  --cyan: #58e6cf;
  --amber: #ffc266;
  --violet: #b58cff;
  --danger: #ff6b6b;
  --radius: 16px;
  --safe-t: env(safe-area-inset-top, 0px);
  --safe-b: env(safe-area-inset-bottom, 0px);
  --font: system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  --serif: ui-serif, Georgia, "Times New Roman", serif;
}

* { box-sizing: border-box; -webkit-tap-highlight-color: transparent; }
html, body { height: 100%; }
body {
  margin: 0;
  background: var(--bg);
  color: var(--ink);
  font-family: var(--font);
  overflow: hidden;
  overscroll-behavior: none;
  -webkit-font-smoothing: antialiased;
}
button { font: inherit; color: inherit; border: 0; background: none; cursor: pointer; touch-action: manipulation; }
button:focus-visible { outline: 2px solid var(--cyan); outline-offset: 2px; }
.hidden { display: none !important; }

/* şehir arka planı */
.city { position: fixed; inset: 0; overflow: hidden; pointer-events: none; z-index: 0; }
.city-glow { position: absolute; border-radius: 50%; filter: blur(70px); opacity: .5; }
.city-glow-a { width: 70vw; height: 50vh; right: -20vw; top: -12vh; background: radial-gradient(circle, rgba(255, 60, 120, .30), transparent 65%); }
.city-glow-b { width: 75vw; height: 45vh; left: -25vw; bottom: -10vh; background: radial-gradient(circle, rgba(50, 220, 220, .20), transparent 65%); }
.rain {
  position: absolute; inset: -30% -10%;
  background-image: repeating-linear-gradient(102deg, transparent 0 22px, rgba(255,255,255,.055) 22px 23px, transparent 23px 47px);
  animation: rain 9s linear infinite;
  opacity: .55;
}
@keyframes rain { to { transform: translate3d(-45px, 240px, 0); } }

/* ekran iskeleti */
#app { position: relative; z-index: 1; height: 100vh; height: 100dvh; }
.screen {
  position: fixed; inset: 0;
  width: 100%; max-width: 620px; margin: 0 auto;
  display: none; flex-direction: column;
  padding: calc(var(--safe-t) + 8px) 14px calc(var(--safe-b) + 8px);
  border-left: 1px solid rgba(255,255,255,.035);
  border-right: 1px solid rgba(255,255,255,.035);
}
.screen.active { display: flex; }
@media (min-width: 640px) {
  body { background: radial-gradient(ellipse at 50% 20%, #111827 0%, #05070c 70%); }
  .screen { padding-left: 22px; padding-right: 22px; background: linear-gradient(180deg, rgba(9,12,19,.55), rgba(7,10,17,.8)); }
}

.scroll-area, .story, .wr-grid { scrollbar-width: none; }
.scroll-area::-webkit-scrollbar, .story::-webkit-scrollbar, .wr-grid::-webkit-scrollbar { display: none; }

/* ortak */
.kicker { font-size: 10px; letter-spacing: .18em; color: var(--pink-soft); font-weight: 700; text-transform: uppercase; }
.screen-head { display: flex; align-items: flex-start; justify-content: space-between; gap: 10px; padding: 4px 2px 10px; flex: 0 0 auto; }
.screen-head h2 { margin: 3px 0 0; font-size: clamp(19px, 5.4vw, 24px); font-weight: 800; letter-spacing: -.02em; }
.icon-btn {
  min-width: 38px; height: 34px; padding: 0 10px;
  border: 1px solid var(--line); border-radius: 10px;
  background: rgba(255,255,255,.045); color: var(--dim);
  font-size: 12px; font-weight: 600; letter-spacing: .02em;
}
.icon-btn:active { background: rgba(255,255,255,.12); }
.clock { font-variant-numeric: tabular-nums; font-size: 11px; letter-spacing: .16em; color: var(--dim); }

.btn {
  position: relative; display: inline-flex; align-items: center; justify-content: center;
  min-height: 48px; padding: 12px 18px;
  border-radius: 14px; border: 1px solid var(--line);
  background: rgba(255,255,255,.055); color: var(--ink);
  font-weight: 700; font-size: 14px; letter-spacing: .01em;
  transition: transform .12s ease, background .2s ease;
}
.btn:active { transform: scale(.98); }
.btn.primary {
  background: linear-gradient(135deg, rgba(255,92,138,.95), rgba(255,127,80,.92));
  border-color: rgba(255,255,255,.18);
  color: #190a10;
  box-shadow: 0 8px 30px rgba(255,92,138,.25);
}
.btn.big { width: 100%; }
.btn.ghost { background: transparent; color: var(--dim); border-color: transparent; font-weight: 600; min-height: 40px; font-size: 13px; }
.btn.ghost:active { background: rgba(255,255,255,.04); }

/* ============ BAŞLIK ============ */
#scr-title { justify-content: center; overflow-y: auto; }
.title-wrap { display: flex; flex-direction: column; align-items: flex-start; padding: 26px 6px 12px; max-width: 460px; }
.title-sign { display: flex; flex-direction: column; gap: 6px; margin-bottom: 18px; }
.sign-kr { font-size: 12px; letter-spacing: .5em; color: var(--cyan); opacity: .9; }
.sign-line { width: 46px; height: 2px; background: linear-gradient(90deg, var(--pink), transparent); }
.sign-tr { font-size: 9px; letter-spacing: .26em; color: var(--dim-2); font-weight: 700; }
.logo {
  margin: 0; font-family: var(--serif); font-weight: 700;
  font-size: clamp(52px, 18vw, 86px); line-height: .86; letter-spacing: -.055em;
  color: #f7f3ef;
  text-shadow: 0 0 44px rgba(255, 92, 138, .16);
}
.logo em {
  font-style: normal;
  background: linear-gradient(100deg, var(--pink) 10%, #ffb36b 55%, var(--pink-soft) 100%);
  -webkit-background-clip: text; background-clip: text; color: transparent;
}
.tagline { margin: 20px 0 0; font-size: 13.5px; line-height: 1.65; color: var(--dim); max-width: 34ch; }
.title-rules { display: flex; flex-wrap: wrap; gap: 8px; align-items: center; margin: 18px 0 22px; font-size: 9px; letter-spacing: .14em; color: var(--dim-2); font-weight: 700; }
.title-rules i { color: var(--pink); font-style: normal; }
.title-actions { width: 100%; display: flex; flex-direction: column; gap: 8px; }
.title-foot { margin: 24px 0 0; font-size: 10.5px; line-height: 1.7; color: var(--dim-2); letter-spacing: .04em; }
.title-foot span { color: rgba(255,255,255,.34); }

/* ============ OYUN ============ */
#scr-game { padding-left: 12px; padding-right: 12px; }
.topbar { display: flex; align-items: center; justify-content: space-between; gap: 8px; flex: 0 0 auto; padding: 1px 2px 6px; }
.night-chip {
  display: flex; align-items: center; gap: 6px;
  font-size: 9px; letter-spacing: .16em; color: var(--dim-2); font-weight: 700;
  padding: 5px 9px; border: 1px solid var(--line); border-radius: 999px; background: rgba(255,255,255,.03);
}
.night-chip b { color: var(--pink-soft); font-size: 11px; letter-spacing: .02em; }
.topbar-right { display: flex; align-items: center; gap: 8px; }
.rank-mini { font-size: 9px; letter-spacing: .1em; color: var(--dim-2); max-width: 90px; text-align: right; line-height: 1.2; font-weight: 700; }

.meters { display: grid; grid-template-columns: 1fr 1fr; gap: 5px 12px; flex: 0 0 auto; padding: 2px 2px 6px; }
.meter-top { display: flex; align-items: baseline; justify-content: space-between; gap: 4px; }
.meter-top span { font-size: 8px; letter-spacing: .13em; color: var(--dim-2); font-weight: 700; }
.meter-top b { font-size: 9.5px; color: var(--dim); font-variant-numeric: tabular-nums; font-weight: 600; }
.meter-bar { height: 3px; margin-top: 3px; border-radius: 99px; background: rgba(255,255,255,.08); overflow: hidden; }
.meter-bar i { display: block; height: 100%; width: 50%; border-radius: 99px; background: var(--pink); transition: width .45s ease, background .4s ease; }
.meter[data-m="energy"] .meter-bar i { background: var(--amber); }
.meter[data-m="foot"] .meter-bar i { background: var(--violet); }
.meter[data-m="hygiene"] .meter-bar i { background: var(--cyan); }
.meter.low .meter-bar i { background: var(--danger) !important; }

.chips { display: flex; gap: 5px; flex: 0 0 auto; overflow-x: auto; padding: 0 2px 7px; min-height: 23px; scrollbar-width: none; }
.chips::-webkit-scrollbar { display: none; }
.chip {
  flex: 0 0 auto; font-size: 8.5px; letter-spacing: .06em; font-weight: 700;
  padding: 4px 8px; border-radius: 999px; border: 1px solid var(--line);
  color: var(--dim-2); background: rgba(255,255,255,.025); white-space: nowrap;
}
.chip.on { color: #0c1117; background: var(--cyan); border-color: transparent; }
.chip.warn { color: #1a0b10; background: var(--pink); border-color: transparent; }
.chip.dim { color: var(--dim-2); }

.story { flex: 1 1 auto; min-height: 0; overflow-y: auto; overscroll-behavior: contain; padding: 4px 4px 8px; }
.event-card {
  position: relative;
  border: 1px solid var(--line); border-radius: var(--radius);
  background: linear-gradient(160deg, rgba(28,34,50,.86), rgba(13,17,27,.88));
  padding: 15px 15px 16px;
  box-shadow: 0 18px 50px rgba(0,0,0,.28);
  animation: cardin .32s ease both;
}
@keyframes cardin { from { opacity: 0; transform: translateY(7px); } to { opacity: 1; transform: none; } }
.event-card::before {
  content: ""; position: absolute; left: 0; top: 14px; bottom: 14px; width: 2px;
  background: linear-gradient(180deg, var(--pink), rgba(255,92,138,0));
  border-radius: 2px;
}
.event-kicker { display: flex; align-items: center; gap: 8px; font-size: 8.5px; letter-spacing: .16em; color: var(--pink-soft); font-weight: 700; text-transform: uppercase; }
.event-kicker i { flex: 0 0 12px; height: 1px; background: rgba(255,255,255,.2); }
.event-kicker span:last-child { color: var(--dim-2); letter-spacing: .1em; }
.event-card h2 { margin: 8px 0 7px; font-size: clamp(19px, 5.2vw, 23px); line-height: 1.15; letter-spacing: -.02em; font-weight: 800; }
.event-card p { margin: 0; font-size: 13.6px; line-height: 1.66; color: #d3d8e4; }
.outcome { display: flex; flex-direction: column; gap: 5px; margin-top: 10px; }
.outcome:empty { display: none; }
.outcome-line {
  font-size: 10.5px; line-height: 1.5; color: var(--cyan);
  border-left: 2px solid rgba(88,230,207,.4); padding: 2px 0 2px 8px;
}
.outcome-line.bad { color: var(--pink-soft); border-color: rgba(255,92,138,.4); }
.outcome-line.good { color: var(--cyan); }

.choices { display: grid; grid-template-columns: 1fr 1fr; gap: 7px; flex: 0 0 auto; padding-top: 7px; }
.choice {
  position: relative;
  display: flex; align-items: flex-start; gap: 8px;
  min-height: 58px; padding: 9px 10px;
  border: 1px solid rgba(255,255,255,.10); border-radius: 13px;
  background: linear-gradient(150deg, rgba(35,42,60,.92), rgba(17,22,34,.95));
  text-align: left;
  transition: border-color .18s ease, background .18s ease, transform .1s ease;
  overflow: hidden;
}
.choice::after {
  content: ""; position: absolute; inset: 0;
  background: linear-gradient(120deg, rgba(255,92,138,.11), transparent 50%);
  opacity: 0; transition: opacity .2s ease;
}
.choice:active { transform: scale(.985); border-color: rgba(255,92,138,.5); }
.choice:active::after { opacity: 1; }
.choice .k {
  flex: 0 0 17px; height: 17px; border-radius: 5px;
  display: inline-flex; align-items: center; justify-content: center;
  font-size: 8.5px; font-weight: 800; color: var(--pink-soft);
  border: 1px solid rgba(255,92,138,.3); background: rgba(255,92,138,.08);
  margin-top: 1px;
}
.choice .t { font-size: 11.8px; line-height: 1.32; color: #dde2ec; font-weight: 600; }
.choice.risky .k { color: var(--amber); border-color: rgba(255,194,102,.3); background: rgba(255,194,102,.08); }
.choice.soft .k { color: var(--cyan); border-color: rgba(88,230,207,.3); background: rgba(88,230,207,.08); }
.choice:disabled { opacity: .55; }

/* ağlama efekti */
#scr-game.teary .event-card p { filter: blur(.35px); color: #c4cbd9; }
#scr-game.teary .story { background: radial-gradient(ellipse at 50% 100%, rgba(88,230,207,.05), transparent 60%); }
.tears { position: absolute; inset: 0; pointer-events: none; opacity: 0; transition: opacity .5s ease; z-index: 5; }
.tears.on { opacity: 1; }
.tears i {
  position: absolute; top: 12%; width: 2px; height: 14px; border-radius: 50%;
  background: linear-gradient(180deg, transparent, rgba(180, 240, 255, .7));
  animation: drop 2.4s linear infinite;
}
@keyframes drop { 0% { transform: translateY(0); opacity: 0; } 15% { opacity: .9; } 100% { transform: translateY(68vh); opacity: 0; } }

/* ============ GİRİŞ ============ */
#scr-intro .scroll-area { flex: 1; min-height: 0; overflow-y: auto; padding: 4px 2px 10px; }
.intro-prose p { font-size: 13.8px; line-height: 1.75; color: #d4d9e5; margin: 0 0 13px; }
.intro-prose p:first-child::first-letter { font-family: var(--serif); font-size: 2.4em; float: left; line-height: .9; padding: 5px 7px 0 0; color: var(--pink); }
.intro-prose .kr { color: var(--dim-2); font-size: 11px; letter-spacing: .3em; }
.intro-choices { display: flex; flex-direction: column; gap: 7px; padding-top: 8px; }

/* ============ BRİFİNG ============ */
#scr-brief .scroll-area, #scr-dawn .scroll-area { flex: 1; min-height: 0; overflow-y: auto; padding: 2px 2px 12px; }
.case-brief {
  border: 1px solid var(--line); border-radius: 15px;
  background: linear-gradient(150deg, rgba(28,35,52,.9), rgba(13,17,27,.9));
  padding: 13px 14px; margin-bottom: 9px;
}
.case-brief .cc { font-size: 9px; letter-spacing: .15em; color: var(--pink-soft); font-weight: 700; }
.case-brief h3 { margin: 5px 0 4px; font-size: 17px; letter-spacing: -.01em; }
.case-brief p { margin: 0; font-size: 11.5px; line-height: 1.55; color: var(--dim); }
.case-brief .loc { display: inline-block; margin-top: 7px; font-size: 9px; letter-spacing: .1em; color: var(--cyan); border: 1px solid rgba(88,230,207,.25); border-radius: 999px; padding: 3px 8px; }
.outfit-line {
  display: flex; justify-content: space-between; gap: 10px;
  font-size: 10px; color: var(--dim-2); padding: 0 2px 12px; line-height: 1.5;
}
.outfit-line b { color: var(--dim); font-weight: 600; }
.prompt { font-size: 11px; letter-spacing: .1em; color: var(--dim-2); font-weight: 700; margin: 4px 2px 8px; text-transform: uppercase; }
.route-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 8px; }
.route {
  position: relative; text-align: left; padding: 12px 11px 13px;
  border: 1px solid var(--line); border-radius: 14px;
  background: linear-gradient(155deg, rgba(31,38,55,.88), rgba(14,18,29,.92));
  display: flex; flex-direction: column; gap: 5px; min-height: 116px;
  transition: border-color .18s ease, transform .1s ease;
}
.route:active { transform: scale(.98); border-color: rgba(88,230,207,.45); }
.route .ri { font-size: 17px; color: var(--cyan); line-height: 1; }
.route h4 { margin: 0; font-size: 13px; font-weight: 800; letter-spacing: -.01em; }
.route p { margin: 0; font-size: 9.8px; line-height: 1.5; color: var(--dim); }
.route .rmods { display: flex; flex-wrap: wrap; gap: 4px; margin-top: auto; padding-top: 3px; }
.route .rmods span { font-size: 8px; letter-spacing: .06em; color: var(--dim-2); border: 1px solid var(--line); border-radius: 99px; padding: 2px 5px; }
.fine-note { margin: 12px 2px 0; font-size: 9.5px; line-height: 1.6; color: var(--dim-2); }

/* ============ SABAH ============ */
.report { border: 1px solid var(--line); border-radius: 15px; background: rgba(255,255,255,.028); padding: 13px 14px; margin-bottom: 9px; }
.report-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 9px 14px; }
.report-item span { display: block; font-size: 8px; letter-spacing: .13em; color: var(--dim-2); font-weight: 700; margin-bottom: 2px; }
.report-item b { font-size: 12px; font-weight: 600; color: var(--ink); }
.report-item b.bad { color: var(--pink-soft); }
.report-item b.good { color: var(--cyan); }
.report .r-title { font-size: 10px; letter-spacing: .14em; color: var(--amber); font-weight: 700; margin-bottom: 9px; }
.outcome-box { font-size: 11.5px; line-height: 1.6; color: var(--dim); border-left: 2px solid rgba(255,92,138,.4); padding: 4px 0 4px 10px; margin: 0 2px 12px; }
.outcome-box:empty { display: none; }
.dawn-choices { display: flex; flex-direction: column; gap: 7px; }
.dawn-choice {
  display: flex; align-items: center; gap: 10px; text-align: left;
  padding: 11px 12px; border-radius: 13px; border: 1px solid var(--line);
  background: linear-gradient(150deg, rgba(31,38,55,.86), rgba(15,19,30,.92));
  min-height: 52px; transition: border-color .18s ease, transform .1s ease;
}
.dawn-choice:active { border-color: rgba(88,230,207,.45); transform: scale(.99); }
.dawn-choice .di { font-size: 17px; width: 22px; text-align: center; }
.dawn-choice .dt { font-size: 11.5px; line-height: 1.4; color: #dce1eb; font-weight: 600; }
.dawn-choice .dt small { display: block; font-size: 9.5px; color: var(--dim-2); font-weight: 400; margin-top: 2px; }
#btnDawnNext { margin-top: 10px; }
.dawn-clock { color: var(--amber) !important; }

/* ============ DOLAP ============ */
#scr-wardrobe { padding-bottom: calc(var(--safe-b) + 8px); }
.wardrobe-head { padding-bottom: 7px; }
.wr-head-right { display: flex; align-items: center; gap: 7px; }
.wr-count { font-size: 9px; letter-spacing: .08em; color: var(--dim-2); }
.wr-preview-wrap {
  display: flex; gap: 10px; align-items: stretch;
  border: 1px solid var(--line); border-radius: 15px;
  background: linear-gradient(150deg, rgba(28,34,50,.75), rgba(12,16,25,.9));
  padding: 7px; flex: 0 0 auto; height: clamp(118px, 20vh, 152px);
  margin-bottom: 8px;
}
.wr-preview { flex: 0 0 48%; border-radius: 10px; overflow: hidden; background: radial-gradient(ellipse at 50% 30%, rgba(255,92,138,.10), transparent 65%), #0b0f18; }
.wr-preview svg { display: block; width: 100%; height: 100%; }
.wr-preview-info { flex: 1; min-width: 0; display: flex; flex-direction: column; justify-content: center; gap: 6px; padding-right: 3px; }
.wr-look-name { font-size: 12px; font-weight: 800; line-height: 1.25; letter-spacing: -.01em; }
.wr-look-name small { display: block; font-size: 9px; font-weight: 500; color: var(--dim-2); margin-top: 2px; letter-spacing: .05em; }
.wr-stats { display: flex; flex-direction: column; gap: 3px; }
.wr-stat { display: flex; align-items: center; gap: 6px; font-size: 8.5px; color: var(--dim-2); }
.wr-stat span { flex: 0 0 42px; letter-spacing: .04em; }
.wr-stat i { flex: 1; height: 3px; border-radius: 99px; background: rgba(255,255,255,.08); overflow: hidden; }
.wr-stat i b { display: block; height: 100%; background: var(--cyan); border-radius: 99px; }
.wr-stat.warn i b { background: var(--pink); }

.wr-tabs { display: flex; gap: 5px; margin-bottom: 7px; flex: 0 0 auto; }
.wr-tab {
  flex: 1; padding: 8px 6px; border-radius: 10px; border: 1px solid var(--line);
  background: rgba(255,255,255,.03); color: var(--dim-2); font-size: 11px; font-weight: 700; letter-spacing: .04em;
}
.wr-tab.active { background: rgba(255,92,138,.13); border-color: rgba(255,92,138,.35); color: var(--pink-soft); }
.wr-filters { display: flex; gap: 5px; overflow-x: auto; padding: 0 1px 7px; flex: 0 0 auto; scrollbar-width: none; }
.wr-filters::-webkit-scrollbar { display: none; }
.wr-filter {
  flex: 0 0 auto; font-size: 9px; font-weight: 600; letter-spacing: .05em;
  padding: 5px 9px; border-radius: 999px; border: 1px solid var(--line);
  color: var(--dim-2); background: rgba(255,255,255,.02);
}
.wr-filter.active { background: rgba(88,230,207,.12); border-color: rgba(88,230,207,.32); color: var(--cyan); }
.wr-grid { flex: 1 1 auto; min-height: 0; overflow-y: auto; display: grid; grid-template-columns: 1fr 1fr; gap: 6px; padding: 1px 1px 6px; overscroll-behavior: contain; }
.wr-item {
  display: flex; align-items: flex-start; gap: 8px; text-align: left;
  padding: 8px 9px; min-height: 50px;
  border: 1px solid var(--line); border-radius: 11px;
  background: rgba(255,255,255,.028);
  transition: border-color .15s ease, background .15s ease;
}
.wr-item.sel { border-color: rgba(255,92,138,.7); background: rgba(255,92,138,.09); box-shadow: 0 0 0 1px rgba(255,92,138,.2) inset; }
.wr-swatch {
  flex: 0 0 20px; height: 20px; margin-top: 1px; border-radius: 50%;
  border: 1px solid rgba(255,255,255,.22);
  box-shadow: inset 0 -5px 7px rgba(0,0,0,.35);
}
.wr-swatch.shoe-swatch { border-radius: 6px 9px 5px 6px; height: 16px; margin-top: 3px; }
.wr-meta { min-width: 0; }
.wr-name { display: block; font-size: 10.5px; line-height: 1.28; font-weight: 700; color: #e4e8f0; }
.wr-sub { display: block; font-size: 8px; line-height: 1.4; color: var(--dim-2); margin-top: 2px; letter-spacing: .03em; }
.wr-footer { flex: 0 0 auto; padding-top: 7px; border-top: 1px solid rgba(255,255,255,.06); }
.wr-footer .btn { min-height: 46px; font-size: 13px; }

/* ============ MODAL ============ */
.modal { position: fixed; inset: 0; z-index: 40; background: rgba(4,6,11,.72); backdrop-filter: blur(8px); -webkit-backdrop-filter: blur(8px); display: flex; align-items: flex-end; justify-content: center; padding: 12px; }
.modal-card {
  width: 100%; max-width: 540px; max-height: 84vh; max-height: 84dvh;
  border: 1px solid rgba(255,255,255,.12); border-radius: 20px;
  background: linear-gradient(170deg, #151b29, #0a0e17);
  display: flex; flex-direction: column; overflow: hidden;
  animation: up .24s ease both;
}
@keyframes up { from { transform: translateY(16px); opacity: .6; } to { transform: none; opacity: 1; } }
.modal-head { display: flex; align-items: center; justify-content: space-between; padding: 13px 14px 10px; border-bottom: 1px solid var(--line); flex: 0 0 auto; }
.modal-head h3 { margin: 0; font-size: 15px; letter-spacing: -.01em; }
.modal-body { padding: 13px 15px calc(18px + var(--safe-b)); overflow-y: auto; font-size: 12.5px; line-height: 1.65; color: #cfd5e1; }
.modal-body h4 { margin: 16px 0 6px; font-size: 11px; letter-spacing: .12em; color: var(--pink-soft); text-transform: uppercase; }
.modal-body p { margin: 0 0 9px; }
.modal-body ul { padding-left: 17px; margin: 0 0 10px; }
.modal-body li { margin-bottom: 5px; }
.modal-body .log-entry { border-bottom: 1px solid rgba(255,255,255,.06); padding: 9px 0 10px; }
.modal-body .log-entry:last-child { border-bottom: 0; }
.log-night { font-size: 8.5px; letter-spacing: .14em; color: var(--dim-2); font-weight: 700; }
.log-title { font-size: 12px; font-weight: 700; margin: 2px 0 2px; color: #e8ecf4; }
.log-choice { font-size: 10.5px; color: var(--cyan); }
.log-choice::before { content: "↳ "; opacity: .7; }

/* toast */
.toast {
  position: fixed; left: 50%; bottom: calc(76px + var(--safe-b)); transform: translate(-50%, 12px);
  z-index: 50; max-width: 86vw; padding: 8px 13px; border-radius: 999px;
  font-size: 10.5px; font-weight: 600; color: #0a1016; background: var(--cyan);
  opacity: 0; pointer-events: none; transition: opacity .25s ease, transform .25s ease;
  text-align: center; line-height: 1.35;
}
.toast.show { opacity: 1; transform: translate(-50%, 0); }

/* küçük ekran / kısa ekran uyumu */
@media (max-height: 700px) {
  .event-card { padding: 12px 13px 13px; }
  .event-card p { font-size: 12.8px; line-height: 1.6; }
  .choice { min-height: 52px; padding: 7px 9px; }
  .choice .t { font-size: 11px; }
  .wr-preview-wrap { height: 108px; }
  .meters { gap: 3px 12px; }
  .logo { font-size: clamp(46px, 15vw, 70px); }
}
@media (max-height: 620px) {
  .topbar, .meters, .chips { padding-bottom: 4px; }
  .event-card h2 { font-size: 17px; margin: 6px 0 5px; }
  .event-card p { font-size: 12.2px; }
  .choice { min-height: 48px; }
  .choice .t { font-size: 10.5px; }
  .wr-preview-wrap { height: 96px; }
  .wr-tabs { margin-bottom: 5px; }
  .wr-tab { padding: 6px; }
  .wr-grid { gap: 5px; }
}
@media (min-width: 430px) {
  .wr-grid { grid-template-columns: 1fr 1fr 1fr; }
  .choices { gap: 8px; }
}
@media (min-width: 700px) {
  .screen { border-radius: 0; }
  .event-card p { font-size: 14.5px; }
  .choice .t { font-size: 12.5px; }
}
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { animation-duration: .001ms !important; animation-iteration-count: 1 !important; transition-duration: .001ms !important; }
  .rain { display: none; }
}

/* Gece Devriyesi — oyun motoru */
(() => {
  'use strict';

  const SAVE_KEY = 'gece-devriyesi-v1';
  const $ = (sel) => document.querySelector(sel);
  const $$ = (sel) => Array.from(document.querySelectorAll(sel));
  const clamp = (v, a = 0, b = 100) => Math.max(a, Math.min(b, v));
  const rnd = (n) => Math.floor(Math.random() * n);
  const esc = (t) => String(t).replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
  const money = (n) => String(n).padStart(2, '0');

  const POOLS = {
    foot: ['i_su', 'i_kum', 'i_topuk', 'i_corap', 'i_tayt', 'i_koku'],
    mind: ['i_agla', 'i_ayna', 'i_arkadas', 'i_kedi', 'i_kahve'],
    street: ['i_radyo', 'i_yagmur', 'i_kaza', 'i_kahve'],
    city: ['i_ayna', 'i_kedi', 'i_yagmur', 'i_kahve'],
    talk: ['k_tanik', 'k_telefon'],
    clue: ['k_iz', 'k_tanik', 'k_kamera', 'k_telefon', 'k_dur'],
    chase: ['k_sokak', 'k_dur'],
    quiet: ['i_kahve', 'i_ayna', 'i_kedi', 'i_arkadas'],
  };

  const ROUTE_QUEUE = {
    sahil: ['i_kum', 'k_iz', 'i_su'],
    liman: ['k_kamera', 'i_koku', 'k_tanik'],
    merkez: ['i_arkadas', 'i_kahve', 'k_tanik'],
    tunel: ['i_tayt', 'k_sokak', 'i_corap'],
  };

  const TEMPERAMENTS = [
    {
      id: 'titiz', label: 'Titiz ve mesafeli', desc: 'Her şey yerinde olsun. Ayakkabı temiz, üniforma düzgün, duygular kilitli.',
      fx: { moral: 56, energy: 98, pain: 8, wet: 0, sand: 0, smell: 0 },
    },
    {
      id: 'duygusal', label: 'Duygusal ve açık', desc: 'Herkesin derdi senin derdin. Ağlamak bir zayıflık değil, sadece bir hava durumu.',
      fx: { moral: 42, energy: 100, pain: 6, wet: 1, sand: 0, smell: 0 },
    },
    {
      id: 'soguk', label: 'Buz gibi sakin', desc: 'Önce gözlem, sonra adım. Kimse senin ne hissettiğini bilmek zorunda değil.',
      fx: { moral: 68, energy: 100, pain: 10, wet: 0, sand: 0, smell: 0 },
    },
    {
      id: 'cilgin', label: 'Çılgın ve hazır', desc: 'Gece uzun, sen daha uzun. Renkli çorap, yüksek topuk, sıfır plan.',
      fx: { moral: 58, energy: 94, pain: 5, wet: 0, sand: 1, smell: 0 },
    },
  ];

  const DAWN_OPTIONS = [
    {
      icon: '≈', label: 'Sıcak sabunlu küvet', sub: 'Islak, kumlu, kokulu — hepsini temizler. Biraz yorucu.',
      run: (st) => {
        st.wet = 0; st.sand = 0; st.smell = Math.max(0, st.smell - 2);
        st.pain = clamp(st.pain - 24); st.moral = clamp(st.moral + 5); st.energy = clamp(st.energy - 4);
        return 'Ayaklarını sabunladın. Suyun rengi griye döndü; taytını çıkarırken bacağında lastik izlerini gördün.';
      },
    },
    {
      icon: '▭', label: 'Islak mendil ve kuru çorap', sub: 'Hızlı bir çözüm. Her şeyi temizlemez ama idare eder.',
      run: (st) => {
        st.wet = Math.max(0, st.wet - 1); st.sand = Math.max(0, st.sand - 1);
        st.smell = Math.max(0, st.smell - 1); st.pain = clamp(st.pain - 10);
        st.moral = clamp(st.moral + 1); st.energy = clamp(st.energy - 1);
        return 'Islak mendille ayak parmaklarının arasını sildin. Kumun bir kısmı hâlâ orada; kabul ettin.';
      },
    },
    {
      icon: '◌', label: 'Çorapları çıkar, ayaklarını havalandır', sub: 'Naylonu çıkar, tenini serbest bırak. Koku ve ağrı azalır.',
      run: (st) => {
        st.sand = Math.max(0, st.sand - 1); st.smell = Math.max(0, st.smell - 1);
        st.pain = clamp(st.pain - 14); st.moral = clamp(st.moral + 3); st.energy = clamp(st.energy + 4);
        return 'Çorapları çıkardın. Ayakların çıplak, hafif ve biraz utanmış. Pencereden gelen sabah ışığı tenini ısıttı.';
      },
    },
    {
      icon: '—', label: 'Hiçbir şey yapma, doğru yatağa', sub: 'Uyku her şeyi çözer mi? Hayır. Ama enerji verir.',
      run: (st) => {
        st.energy = clamp(st.energy + 20); st.moral = clamp(st.moral - 7);
        st.pain = clamp(st.pain - 4); st.smell = Math.min(3, st.smell + 1);
        return 'Ayakkabıları tekmeyle çıkardın, yatağa düştün. Odada ince bir deniz kokusu kaldı.';
      },
    },
  ];

  let s = null;
  let lock = false;
  const ui = { tab: 'socks', filter: 'all', wrFrom: 'title', toastTimer: null };

  /* ---------- durum ---------- */
  function newState() {
    const order = [0, 1, 2, 3, 4, 5, 6, 7];
    for (let i = order.length - 1; i > 0; i--) { const j = rnd(i + 1); [order[i], order[j]] = [order[j], order[i]]; }
    return {
      v: 1, screen: 'title',
      night: 1, beat: 0, current: null, queue: [],
      moral: 56, energy: 100, pain: 8, wet: 0, sand: 0, smell: 0, clues: 0,
      sock: 'k02', shoe: 'a01',
      caseIndex: order[0], caseOrder: order, route: null, minutes: 30,
      xp: 0, solved: 0, cried: 0, flags: {}, chain: 0,
      log: [], finaleLine: '', dawnDone: false, dawnLine: '', lastResult: '',
      introDone: false, seen: {}, nightDone: false,
    };
  }

  function save() {
    try {
      if (!s) return;
      const copy = Object.assign({}, s);
      localStorage.setItem(SAVE_KEY, JSON.stringify(copy));
    } catch (e) { /* depolama kapalı olabilir */ }
  }

  function loadSave() {
    try {
      const raw = localStorage.getItem(SAVE_KEY);
      if (!raw) return null;
      const data = JSON.parse(raw);
      if (!data || data.v !== 1) return null;
      data.log = data.log || [];
      data.flags = data.flags || {};
      data.seen = data.seen || {};
      data.caseOrder = data.caseOrder || [0, 1, 2, 3, 4, 5, 6, 7];
      return data;
    } catch (e) { return null; }
  }

  function hasSave() { return !!loadSave(); }

  /* ---------- yardımcılar ---------- */
  function rankName() {
    const idx = Math.floor(s.xp / 45);
    if (idx >= RANKS.length) return RANKS[RANKS.length - 1] + ' ✦' + (idx - RANKS.length + 1);
    return RANKS[idx];
  }
  function rankNext() {
    const idx = Math.floor(s.xp / 45);
    if (idx >= RANKS.length) return null;
    return 45 - (s.xp % 45);
  }
  function clockText() {
    const total = 23 * 60 + 10 + s.minutes;
    return `${money(Math.floor(total / 60) % 24)}:${money(total % 60)}`;
  }
  function comfort() { return clamp(100 - s.pain); }
  function hygiene() { return clamp(100 - (s.wet * 10 + s.sand * 10 + s.smell * 16)); }
  function footLabel() {
    if (s.smell >= 3) return 'deniz suyu kokuyor';
    if (s.smell === 2) return 'tuz kokusu var';
    if (s.wet >= 2 && s.sand >= 2) return 'ıslak ve kumlu';
    if (s.wet >= 2) return 'ıslak';
    if (s.sand >= 2) return 'kumlu';
    if (s.pain >= 65) return 'ağrılı';
    return 'iyi';
  }
  function currentCase() { return CASE(s); }

  function footTax() {
    const so = SOCK(s), sh = SHOE(s);
    const rate = 1.1 + so.tight * 0.018 + sh.heel * 0.28 - sh.comfort * 0.025 - so.soft * 0.008;
    s.pain = clamp(s.pain + rate);
    s.energy = clamp(s.energy - 2);
    if ((s.wet > 0 && s.sand > 0) || s.wet >= 2) s.smell = Math.min(3, s.smell + 1);
  }

  /* ---------- ekran ---------- */
  function enter(name) {
    s.screen = name;
    $$('.screen').forEach((el) => el.classList.toggle('active', el.id === 'scr-' + name));
    if (name !== 'game') setTears(false);
  }

  function showToast(text) {
    const el = $('#toast');
    el.textContent = text;
    el.classList.add('show');
    clearTimeout(ui.toastTimer);
    ui.toastTimer = setTimeout(() => el.classList.remove('show'), 2300);
  }

  function setTears(on) {
    $('#scr-game').classList.toggle('teary', !!on);
    $('#tears').classList.toggle('on', !!on);
  }

  function initTears() {
    const box = $('#tears');
    if (box.childElementCount) return;
    for (let i = 0; i < 9; i++) {
      const drop = document.createElement('i');
      drop.style.left = (8 + Math.random() * 84) + '%';
      drop.style.animationDelay = (Math.random() * 2.4).toFixed(2) + 's';
      drop.style.animationDuration = (2 + Math.random() * 1.8).toFixed(2) + 's';
      drop.style.height = (8 + Math.random() * 12).toFixed(0) + 'px';
      box.appendChild(drop);
    }
  }

  /* ---------- HUD ---------- */
  function updateHUD() {
    $('#hudNight').textContent = s.night;
    $('#hudClock').textContent = clockText();
    $('#hudRank').textContent = rankName();

    const vals = {
      moral: s.moral, energy: s.energy, foot: comfort(), hygiene: hygiene(),
    };
    Object.keys(vals).forEach((key) => {
      const v = Math.round(vals[key]);
      $('#mv-' + key).textContent = v;
      $('#mb-' + key).style.width = Math.max(2, v) + '%';
      const meter = $('#mv-' + key).closest('.meter');
      meter.classList.toggle('low', v < 30);
    });

    const chips = [];
    const c = currentCase();
    if (s.route) chips.push(['Rota: ' + s.route.name, '']);
    if (s.screen === 'game' || s.screen === 'brief') chips.push([c.code, 'dim']);
    if (s.wet > 0) chips.push([`ıslak ×${s.wet}`, 'on']);
    if (s.sand > 0) chips.push([`kum ×${s.sand}`, 'on']);
    if (s.smell > 0) chips.push([s.smell >= 2 ? 'deniz kokusu' : 'hafif tuz kokusu', s.smell >= 2 ? 'warn' : '']);
    if (s.pain >= 60) chips.push(['ayak ağrısı', 'warn']);
    if (s.moral < 30) chips.push(['gözyaşı', 'warn']);
    if (s.clues > 0) chips.push([`ipucu ${s.clues}`, '']);
    if (!chips.length) chips.push(['gece sakin', 'dim']);
    $('#chips').innerHTML = chips.map(([t, cls]) => `<span class="chip ${cls}">${esc(t)}</span>`).join('');

    setTears(s.moral < 24 || (s.current === 'i_agla' && s.screen === 'game'));
  }

  /* ---------- giriş ---------- */
  function renderIntro() {
    enter('intro');
    $('#introText').innerHTML = `
      <p>Soyunma odasının floresanı bir tanesi eksik yanıyor. Metal dolabın kapağında adın yazılı: <b>Yuna Seo</b>. Altında, daha küçük: <i>Gece Devriyesi 7</i>.</p>
      <p>Üniformanı giydin. Siyah taytı her zamanki gibi çektin; lastiği belini iki parmak içeri alıyor, diz arkasında ince bir çizgi bırakıyor. Ayağında kadife babet; çantanın içinde otuz dört çorap ve otuz dört ayakkabı daha var. Seçim senin.</p>
      <p>Telsizde santral: “Yuna, gece uzun. Hazır mısın?” Aynada kendine bakıyorsun. Gözlerin parlak. Bu, hazır olmak mı, yoksa dolmak üzere olmak mı, bilmiyorsun.</p>
      <p class="kr">오늘 밤도 순찰</p>
    `;
    $('#introChoices').innerHTML = TEMPERAMENTS.map((t) => `
      <button class="dawn-choice" data-temp="${t.id}">
        <span class="di">✶</span>
        <span class="dt">${esc(t.label)}<small>${esc(t.desc)}</small></span>
      </button>
    `).join('');
    $$('#introChoices .dawn-choice').forEach((btn) => {
      btn.addEventListener('click', () => chooseTemperament(btn.dataset.temp));
    });
    save();
  }

  function chooseTemperament(id) {
    const t = TEMPERAMENTS.find((x) => x.id === id) || TEMPERAMENTS[0];
    s.moral = t.fx.moral; s.energy = t.fx.energy; s.pain = t.fx.pain;
    s.wet = t.fx.wet; s.sand = t.fx.sand; s.smell = t.fx.smell;
    s.introDone = true;
    s.log.push({ night: 1, title: 'Soyunma Odası', choice: t.label });
    ui.wrFrom = 'first';
    enter('wardrobe');
    renderWardrobe();
    save();
  }

  /* ---------- brifing ---------- */
  function renderBrief() {
    enter('brief');
    const c = currentCase();
    s.clues = 0;
    $('#briefKicker').textContent = `GECE ${s.night} • 22:20`;
    $('#briefCase').innerHTML = `
      <div class="cc">${esc(c.code)} • GECE İHBARI</div>
      <h3>${esc(c.title)}</h3>
      <p><b>${esc(c.subject)}</b> — ${esc(c.detail)}. Son görüldüğü yer: ${esc(c.place)}.</p>
      <span class="loc">${esc(c.district)} hattı</span>
    `;
    const so = SOCK(s), sh = SHOE(s);
    $('#briefOutfit').innerHTML = `
      <span><b>${esc(so.name)}</b><br>sıkılık ${so.tight} · acı payı</span>
      <span style="text-align:right"><b>${esc(sh.name)}</b><br>${sh.type} · ${sh.heel} cm · su ${sh.water}</span>
    `;
    $('#routeGrid').innerHTML = ROUTES.map((r) => {
      const mods = [];
      if (r.fx.clues) mods.push('+' + r.fx.clues + ' ipucu');
      if (r.fx.energy) mods.push((r.fx.energy > 0 ? '+' : '') + r.fx.energy + ' enerji');
      if (r.fx.moral) mods.push((r.fx.moral > 0 ? '+' : '') + r.fx.moral + ' duygu');
      if (r.fx.pain) mods.push('+' + r.fx.pain + ' acı');
      if (r.fx.wet) mods.push('+ıslaklık');
      if (r.fx.smell) mods.push('+koku riski');
      if (!mods.length) mods.push('dengeli');
      return `<button class="route" data-route="${r.id}">
        <span class="ri">${r.icon}</span>
        <h4>${esc(r.name)}</h4>
        <p>${esc(r.desc)}</p>
        <span class="rmods">${mods.map((m) => `<span>${esc(m)}</span>`).join('')}</span>
      </button>`;
    }).join('');
    $$('#routeGrid .route').forEach((btn) => btn.addEventListener('click', () => beginNight(btn.dataset.route)));
    updateHUD();
    save();
  }

  function beginNight(routeId) {
    const route = ROUTES.find((r) => r.id === routeId) || ROUTES[0];
    s.route = route;
    s.screen = 'game';
    s.minutes = 30;
    s.beat = 0;
    s.clues = 0;
    s.chain = 0;
    s.finaleLine = '';
    s.lastResult = '';
    s.queue = [];
    Object.entries(route.fx).forEach(([k, v]) => {
      if (['moral', 'energy', 'pain', 'wet', 'sand', 'smell', 'clues'].includes(k)) s[k] = clamp((s[k] || 0) + v, 0, k === 'wet' || k === 'sand' || k === 'smell' ? 3 : 100);
    });
    if (route.fx.clues) s.clues += 0; // fx zaten eklendi

    const c = currentCase();
    const mid = ROUTE_QUEUE[route.id] || ROUTE_QUEUE.merkez;
    s.queue = [c.start, mid[0], mid[1], mid[2], c.end];

    enter('game');
    updateHUD();
    nextFromQueue();
  }

  /* ---------- olay akışı ---------- */
  function nextFromQueue() {
    if (!s.queue.length) { endNight(); return; }
    const id = s.queue.shift();
    showEvent(id);
  }

  function showEvent(id) {
    const ev = EVENTS[id];
    if (!ev) { endNight(); return; }
    lock = false;
    s.current = id;
    s.seen[id] = (s.seen[id] || 0) + 1;
    s.beat += 1;
    s.minutes += 34 + rnd(22);
    if (s.seen[id] === 1) {
      const caseNow = currentCase();
      s.log.push({ night: s.night, title: ev.title, choice: null, id, place: ev.place || caseNow.place });
    }
    enter('game');
    $('#evKicker').textContent = `OLAY ${money(s.beat)}`;
    $('#evPlace').textContent = (id.startsWith('c') && ev.cat === 'end' || ev.cat === 'start') ? currentCase().place : (ev.place || currentCase().place);
    $('#evTitle').textContent = ev.title;
    $('#evText').textContent = typeof ev.text === 'function' ? ev.text(s) : ev.text;
    $('#evOutcome').innerHTML = '';

    const choicesEl = $('#choices');
    choicesEl.innerHTML = ev.choices.map((ch, i) => {
      const risky = (ch.fx && (ch.fx.moral <= -4 || ch.fx.pain >= 5 || ch.fx.rank < 0)) ? 'risky' : ((ch.fx && (ch.fx.moral >= 4 || ch.fx.tag === 'merhamet')) ? 'soft' : '');
      return `<button class="choice ${risky}" data-i="${i}">
        <span class="k">${'ABCD'[i]}</span><span class="t">${esc(ch.label)}</span>
      </button>`;
    }).join('');
    Array.from(choicesEl.children).forEach((btn) => {
      btn.addEventListener('click', () => pick(Number(btn.dataset.i)));
    });
    $('#story').scrollTop = 0;
    updateHUD();
    save();
  }

  function resolveNext(spec) {
    if (!spec) return null;
    if (EVENTS[spec]) return spec;
    if (spec.startsWith('pool:')) {
      const key = spec.slice(5);
      const list = (POOLS[key] || POOLS.clue).filter((id) => id !== s.current);
      const unseen = list.filter((id) => !s.seen[id]);
      const arr = unseen.length && Math.random() < 0.7 ? unseen : list;
      return arr[rnd(arr.length)] || POOLS.clue[0];
    }
    return null;
  }

  function pick(index) {
    if (lock) return;
    const ev = EVENTS[s.current];
    if (!ev) return;
    const ch = ev.choices[index];
    if (!ch) return;
    lock = true;
    $$('#choices .choice').forEach((b) => (b.disabled = true));

    const fb = [];
    const beforeMoral = s.moral;
    applyEffects(ch, fb);

    if (ch.run) {
      const line = ch.run(s);
      if (line) fb.push(line);
    }
    if (ch.endLine) {
      s.finaleLine = typeof ch.endLine === 'function' ? ch.endLine(s) : ch.endLine;
    }
    footTax();

    if (ch.fx && ch.fx.moral >= 5) fb.push('İçindeki oda biraz genişledi.');
    if (ch.fx && ch.fx.moral <= -5 || s.moral < beforeMoral - 6) fb.push('Duygusal sınırın biraz daha inceldi.');
    if (ch.fx && ch.fx.clues) fb.push('Dosyada bir parça daha netleşti.');

    s.log.push({ night: s.night, title: ev.title, choice: ch.label, id: s.current });

    let nextId = ch.next ? resolveNext(ch.next) : null;

    if (nextId && s.queue.length) {
      const upcoming = s.queue[0];
      const upEv = EVENTS[upcoming];
      if (!upEv || upEv.cat !== 'end') s.queue[0] = nextId;
    }

    // olay olayı tetiklesin: kritik eşikler yeni bir sahne açar
    if (s.chain < 2 && s.queue.length) {
      let chainId = null;
      if (s.moral <= 11 && s.current !== 'i_agla') chainId = 'i_agla';
      else if (s.smell >= 3 && s.current !== 'i_koku') chainId = 'i_koku';
      else if (s.pain >= 84 && s.current !== 'i_tayt' && s.current !== 'i_topuk') chainId = 'i_tayt';
      if (chainId && Math.random() < 0.75) {
        s.queue.unshift(chainId);
        s.chain += 1;
      }
    }

    s.minutes += 3 + rnd(6);
    updateHUD();
    save();

    // sonuçları bir sonraki kartta göster
    const pending = fb.slice(0, 3);
    setTimeout(() => {
      if (!s.queue.length) { endNight(pending); return; }
      nextFromQueue();
      if (pending.length) {
        $('#evOutcome').innerHTML = pending.map((line, i) =>
          `<div class="outcome-line ${i === 0 && (s.moral < 30) ? 'bad' : 'good'}">${esc(line)}</div>`).join('');
      }
      updateHUD();
    }, 260);
  }

  function applyEffects(ch, fb) {
    const f = ch.fx || {};
    const numericKeys = ['moral', 'energy', 'pain', 'clues', 'wet', 'sand', 'smell'];
    numericKeys.forEach((k) => {
      if (f[k] == null) return;
      const cap = (k === 'wet' || k === 'sand' || k === 'smell') ? 3 : 100;
      const prev = s[k] || 0;
      s[k] = clamp(prev + f[k], 0, cap);
      const d = s[k] - prev;
      if (k === 'wet' && d > 0) fb.push(`${SOCK(s).name} ıslandı.`);
      if (k === 'sand' && d > 0) fb.push('Ayakkabının içine kum doldu.');
      if (k === 'smell' && d > 0) fb.push('Burnuna ince bir tuz kokusu geldi.');
      if (k === 'pain' && d >= 6) fb.push('Ayakların sızlıyor.');
      if (k === 'energy' && d <= -6) fb.push('Enerjin azaldı.');
    });
    if (f.rank) {
      s.xp = Math.max(0, s.xp + (f.rank > 0 ? f.rank * 2 : f.rank * 2));
    }
    if (f.cry) s.cried += 1;
    if (f.tag) s.flags[f.tag] = (s.flags[f.tag] || 0) + 1;
    s.moral = clamp(s.moral);
  }

  /* ---------- sabah ---------- */
  function endNight(pending) {
    s.screen = 'dawn';
    const c = currentCase();
    const success = s.clues >= 2;
    if (success) s.solved += 1;
    s.xp = Math.max(0, s.xp + 4 + s.clues * 2 + (success ? 4 : 0));
    s.lastResult = success ? 'çözüldü' : (s.clues === 1 ? 'kısmen çözüldü' : 'askıda kaldı');
    s.dawnDone = false;
    s.dawnLine = '';
    s.nightDone = true;
    s.queue = [];
    s.log.push({ night: s.night, title: 'Vardiya Sonu • ' + c.title, choice: `Sonuç: ${s.lastResult}`, id: 'dawn' });
    enter('dawn');
    renderDawn(pending);
    save();
  }

  function dawnStats() {
    return [
      ['Vaka', `${currentCase().title}`],
      ['Sonuç', s.lastResult || '—'],
      ['İpucu', `${s.clues} / 3`],
      ['Ayak', footLabel()],
      ['Hijyen', `${Math.round(hygiene())} / 100`],
      ['Ağrı', `${Math.round(s.pain)} / 100`],
      ['Ağlama', `${s.cried} kez`],
      ['Rütbe', rankName()],
    ];
  }

  function renderDawn(pending) {
    $('#dawnNight').textContent = 'GECE ' + s.night;
    const rows = dawnStats();
    const warn = (label) => ['Ayak', 'Hijyen', 'Ağrı', 'Sonuç'].includes(label);
    $('#dawnReport').innerHTML = `
      <div class="r-title">SABAH RAPORU</div>
      <div class="report-grid">
        ${rows.map(([k, v]) => `
          <div class="report-item">
            <span>${esc(k)}</span>
            <b class="${warn(k) ? 'bad' : ''}">${esc(v)}</b>
          </div>`).join('')}
      </div>
    `;
    $('#dawnOutcome').textContent = s.finaleLine || (pending && pending[0]) || 'Gece bitti. Şehir sustu. Ayakların hâlâ senin.';
    $('#dawnPrompt').classList.toggle('hidden', s.dawnDone);
    $('#dawnChoices').innerHTML = DAWN_OPTIONS.map((d, i) => `
      <button class="dawn-choice" data-i="${i}" ${s.dawnDone ? 'disabled' : ''}>
        <span class="di">${d.icon}</span>
        <span class="dt">${esc(d.label)}<small>${esc(d.sub)}</small></span>
      </button>`).join('');
    $('#dawnChoices').classList.toggle('hidden', s.dawnDone);
    Array.from($('#dawnChoices').children).forEach((btn) => {
      btn.addEventListener('click', () => chooseDawn(Number(btn.dataset.i)));
    });
    const nextBtn = $('#btnDawnNext');
    nextBtn.classList.toggle('hidden', !s.dawnDone);
    $('#dawnNote').textContent = s.dawnLine || (s.smell >= 2 ? 'Ayakkabıların hâlâ nemli. Sabah temizliği önemli.' : 'Dolap seni bekliyor. Yeni gece, yeni seçim.');
    $('#dawnNote').classList.toggle('hidden', !!s.dawnLine && !s.dawnDone);
    if (s.dawnDone) {
      $('#dawnNote').textContent = s.dawnLine;
      $('#dawnNote').classList.remove('hidden');
    }
    updateHUD();
  }

  function chooseDawn(i) {
    if (s.dawnDone) return;
    const opt = DAWN_OPTIONS[i];
    if (!opt) return;
    const line = opt.run(s);
    s.dawnDone = true;
    s.dawnLine = line;
    s.log.push({ night: s.night, title: 'Sabah Temizliği', choice: opt.label });
    renderDawn();
    save();
    showToast(opt.label);
  }

  $('#btnDawnNext').addEventListener('click', () => {
    if (!s.dawnDone) return;
    s.night += 1;
    s.caseIndex = s.caseOrder[(s.night - 1) % s.caseOrder.length];
    s.clues = 0;
    s.finaleLine = '';
    s.lastResult = '';
    s.dawnDone = false;
    s.dawnLine = '';
    s.minutes = 30;
    s.beat = 0;
    s.route = null;
    ui.wrFrom = 'dawn';
    enter('wardrobe');
    renderWardrobe();
    save();
  });

  /* ---------- dolap ---------- */
  function sockTypes() {
    return [
      ['all', 'Tümü'], ['tayt', 'Tayt'], ['külotlu', 'Külotlu'], ['dizaltı', 'Dizaltı'], ['soket', 'Soket'],
    ];
  }
  function shoeTypes() {
    return [
      ['all', 'Tümü'], ['babet', 'Babet'], ['topuklu', 'Topuklu'], ['bot', 'Bot'], ['spor', 'Spor'],
    ];
  }

  function enterWardrobe(from) {
    if (from) ui.wrFrom = from;
    enter('wardrobe');
    renderWardrobe();
    save();
  }

  function renderWardrobe() {
    const isSocks = ui.tab === 'socks';
    $('#wrKicker').textContent = `GECE ${s.night} • HAZIRLIK`;
    $('#wrCount').textContent = isSocks ? '34 çorap' : '34 ayakkabı';
    $('#wrTabs').innerHTML = `
      <button class="wr-tab ${isSocks ? 'active' : ''}" data-tab="socks">Çoraplar</button>
      <button class="wr-tab ${!isSocks ? 'active' : ''}" data-tab="shoes">Ayakkabılar</button>`;
    Array.from($('#wrTabs').children).forEach((b) => b.addEventListener('click', () => {
      if (ui.tab === b.dataset.tab) return;
      ui.tab = b.dataset.tab; ui.filter = 'all'; renderWardrobe();
    }));

    const filters = isSocks ? sockTypes() : shoeTypes();
    if (!filters.some(([id]) => id === ui.filter)) ui.filter = 'all';
    $('#wrFilters').innerHTML = filters.map(([id, label]) =>
      `<button class="wr-filter ${ui.filter === id ? 'active' : ''}" data-f="${id}">${label}</button>`).join('');
    Array.from($('#wrFilters').children).forEach((b) => b.addEventListener('click', () => {
      ui.filter = b.dataset.f; renderWardrobe();
    }));

    const items = isSocks
      ? SOCKS.filter((x) => ui.filter === 'all' || x.type === ui.filter)
      : SHOES.filter((x) => ui.filter === 'all' || x.type === ui.filter);

    const grid = $('#wrGrid');
    grid.innerHTML = items.map((x) => {
      const sel = isSocks ? x.id === s.sock : x.id === s.shoe;
      if (isSocks) {
        return `<button class="wr-item ${sel ? 'sel' : ''}" data-kind="sock" data-id="${x.id}">
          <span class="wr-swatch" style="background:${x.color}"></span>
          <span class="wr-meta">
            <span class="wr-name">${esc(x.name)}</span>
            <span class="wr-sub">${esc(x.type)} · sıkı ${x.tight}</span>
          </span>
        </button>`;
      }
      return `<button class="wr-item ${sel ? 'sel' : ''}" data-kind="shoe" data-id="${x.id}">
        <span class="wr-swatch shoe-swatch" style="background:${x.color}"></span>
        <span class="wr-meta">
          <span class="wr-name">${esc(x.name)}</span>
          <span class="wr-sub">${esc(x.type)} · ${x.heel} cm · konfor ${x.comfort}</span>
        </span>
      </button>`;
    }).join('');
    Array.from(grid.children).forEach((btn) => btn.addEventListener('click', () => {
      if (btn.dataset.kind === 'sock') s.sock = btn.dataset.id;
      else s.shoe = btn.dataset.id;
      save();
      renderWardrobe();
    }));

    updatePreview();
  }

  function updatePreview() {
    const so = SOCK(s), sh = SHOE(s);
    $('#preview').innerHTML = previewSVG(so, sh);
    $('#wrLookName').innerHTML = `${esc(so.name)}<small>${esc(sh.name)} · ${sh.type} · ${sh.heel} cm topuk</small>`;
    const stats = [
      ['SIKI', so.tight, so.tight > 85],
      ['YUMUŞAK', so.soft, false],
      ['SU', sh.water, sh.water < 35],
      ['KUM', sh.sand, sh.sand < 35],
    ];
    $('#wrStats').innerHTML = stats.map(([label, val, warn]) => `
      <div class="wr-stat ${warn ? 'warn' : ''}"><span>${label}</span><i><b style="width:${val}%"></b></i></div>
    `).join('');
  }

  function previewSVG(so, sh) {
    const pat = patternDef(so);
    const shoeColor = sh.color || '#222';
    const isHeel = sh.type === 'topuklu';
    const isBoot = sh.type === 'bot';
    const isSport = sh.type === 'spor';
    const heelPx = Math.min(20, 4 + sh.heel * 1.3);
    const shine = `<linearGradient id="shine" x1="0" y1="0" x2="1" y2="0">
      <stop offset="0" stop-color="#fff" stop-opacity="0"/><stop offset=".38" stop-color="#fff" stop-opacity=".20"/><stop offset=".55" stop-color="#fff" stop-opacity="0"/>
    </linearGradient>`;

    const leg = (cx, mirror) => {
      const top = isBoot ? 44 : -6;
      const legPath = `M${cx - 18} ${top} C${cx - 22} 42 ${cx - 20} 82 ${cx - 17} 110 L${cx + 17} 110 C${cx + 21} 82 ${cx + 22} 42 ${cx + 18} ${top} Z`;
      let shoeShape = '';
      const d = mirror ? 1 : -1;
      if (isHeel) {
        shoeShape = `
          <path d="M${cx - 20} 108 Q${cx + d * 14} 108 ${cx + d * 42} 124 Q${cx + d * 46} 132 ${cx + d * 30} 134 L${cx - 18} 132 Z" fill="${shoeColor}"/>
          <path d="M${cx - 12} 132 L${cx - 9} ${132 + heelPx} L${cx - 3} ${132 + heelPx} L${cx + 2} 132 Z" fill="${shoeColor}"/>
          <path d="M${cx - 24} 132 Q${cx} 139 ${cx + d * 34} 134" fill="none" stroke="rgba(255,255,255,.45)" stroke-width="1.5"/>`;
      } else if (isSport) {
        shoeShape = `
          <path d="M${cx - 22} 106 Q${cx - 30} 126 ${cx - 20} 134 L${cx + 22} 134 Q${cx + d * 30} 132 ${cx + d * 26} 122 Q${cx + d * 14} 108 ${cx + d * 2} 106 Z" fill="${shoeColor}"/>
          <rect x="${cx - 22}" y="132" width="45" height="4" rx="2" fill="rgba(255,255,255,.5)"/>`;
      } else if (isBoot) {
        shoeShape = `
          <path d="M${cx - 20} 58 L${cx + 20} 58 L${cx + 20} 118 Q${cx + 18} 132 ${cx - 4} 133 Q${cx - 24} 132 ${cx - 26} 120 Z" fill="${shoeColor}"/>
          <rect x="${cx - 20}" y="100" width="40" height="2" fill="rgba(255,255,255,.25)"/>
          <path d="M${cx - 22} 131 Q${cx} 137 ${cx + 18} 131" fill="none" stroke="rgba(255,255,255,.4)" stroke-width="2"/>`;
      } else {
        shoeShape = `
          <path d="M${cx - 19} 108 Q${cx + d * 20} 108 ${cx + d * 38} 122 Q${cx + d * 42} 132 ${cx + d * 22} 133 L${cx - 18} 132 Q${cx - 22} 118 ${cx - 20} 108 Z" fill="${shoeColor}"/>
          <ellipse cx="${cx + d * 12}" cy="130" rx="${d * 22}" ry="3" fill="rgba(255,255,255,.25)"/>
          <circle cx="${cx + d * 18}" cy="114" r="2.6" fill="${so.accent}" opacity=".8"/>`;
      }
      return `
        <g>
          <ellipse cx="${cx}" cy="140" rx="29" ry="4" fill="rgba(0,0,0,.4)"/>
          <path d="${legPath}" fill="url(#${pat.id})"/>
          <path d="${legPath}" fill="url(#shine)"/>
          <path d="M${cx - 16} 4 C${cx - 12} 40 ${cx - 12} 78 ${cx - 14} 108" stroke="rgba(255,255,255,.18)" stroke-width="1.2" fill="none"/>
          <rect x="${cx - 18}" y="${isBoot ? 42 : -2}" width="36" height="4" fill="${so.accent}" opacity=".55"/>
          ${shoeShape}
        </g>`;
    };

    return `<svg viewBox="0 0 300 150" preserveAspectRatio="xMidYMid meet" xmlns="http://www.w3.org/2000/svg">
      <defs>${shine}${pat.def}</defs>
      <g opacity=".4" stroke="rgba(255,255,255,.06)" stroke-width=".5">
        ${Array.from({ length: 8 }, (_, i) => `<line x1="0" y1="${i * 19}" x2="300" y2="${i * 19}"/>`).join('')}
        ${Array.from({ length: 11 }, (_, i) => `<line x1="${i * 30}" y1="0" x2="${i * 30}" y2="150"/>`).join('')}
      </g>
      <ellipse cx="150" cy="141" rx="88" ry="6" fill="rgba(255,92,138,.12)"/>
      ${leg(108, false)}
      ${leg(192, true)}
    </svg>`;
  }

  function patternDef(so) {
    const id = 'sockpat';
    const c = so.color, a = so.accent;
    let inner = `<rect width="12" height="12" fill="${c}"/>`;
    switch (so.pattern) {
      case 'stripe':
        inner += `<rect y="2" width="12" height="3" fill="${a}" opacity=".72"/><rect y="8" width="12" height="1.5" fill="${a}" opacity=".5"/>`;
        break;
      case 'dot':
        inner += `<circle cx="3" cy="3" r="1.1" fill="${a}"/><circle cx="9" cy="9" r="1.1" fill="${a}"/>`;
        break;
      case 'fishnet':
        inner = `<rect width="12" height="12" fill="${c}"/>` +
          `<path d="M0 0L12 12M12 0L0 12" stroke="${a}" stroke-width="1.1" opacity=".8"/>`;
        break;
      case 'glitter':
        inner += `<circle cx="2" cy="4" r=".8" fill="${a}"/><circle cx="8" cy="2" r=".6" fill="#fff" opacity=".8"/><circle cx="6" cy="8" r=".9" fill="${a}"/><circle cx="11" cy="10" r=".5" fill="#fff"/>`;
        break;
      case 'zebra':
        inner += `<path d="M0 3 Q6 0 12 4 L12 6 Q6 2 0 5 Z" fill="${a}" opacity=".85"/><path d="M0 9 Q6 6 12 10 L12 12 Q6 8 0 11 Z" fill="${a}" opacity=".85"/>`;
        break;
      case 'rib':
        inner += `<path d="M3 0V12M9 0V12" stroke="${a}" stroke-width="1" opacity=".35"/>`;
        break;
      case 'lace':
        inner += `<path d="M0 11 Q3 7 6 11 Q9 7 12 11" fill="none" stroke="${a}" stroke-width="1.1"/>`;
        break;
      case 'velvet':
        inner += `<rect width="12" height="12" fill="url(#velvet)"/>`;
        return {
          id,
          def: `<pattern id="${id}" width="12" height="12" patternUnits="userSpaceOnUse">${inner}</pattern>
            <radialGradient id="velvet"><stop offset="0" stop-color="#fff" stop-opacity=".18"/><stop offset="1" stop-color="#000" stop-opacity=".18"/></radialGradient>`,
        };
      case 'sheer':
        return {
          id,
          def: `<pattern id="${id}" width="12" height="12" patternUnits="userSpaceOnUse"><rect width="12" height="12" fill="${c}"/><rect width="12" height="12" fill="#000" opacity=".22"/></pattern>`,
        };
      default:
        return { id, def: `<pattern id="${id}" width="12" height="12" patternUnits="userSpaceOnUse">${inner}${so.pattern === 'shine' ? '<rect width="12" height="12" fill="url(#gloss)"/>' : ''}</pattern><linearGradient id="gloss" x1="0" y1="0" x2="1" y2="0"><stop offset=".2" stop-color="#fff" stop-opacity=".18"/><stop offset=".6" stop-color="#fff" stop-opacity="0"/></linearGradient>` };
    }
    return { id, def: `<pattern id="${id}" width="12" height="12" patternUnits="userSpaceOnUse">${inner}</pattern>` };
  }

  /* ---------- modal ---------- */
  function openModal(title, html) {
    $('#modalTitle').textContent = title;
    $('#modalBody').innerHTML = html;
    $('#modal').classList.remove('hidden');
  }
  function closeModal() { $('#modal').classList.add('hidden'); }
  $('#btnModalClose').addEventListener('click', closeModal);
  $('#modal').addEventListener('click', (e) => { if (e.target === $('#modal')) closeModal(); });

  function helpHTML() {
