    if (ui.wrFrom === 'brief') { renderBrief(); return; }
    refreshTitle();
  });
  $('#btnStartNight').addEventListener('click', () => {
    s.screen = 'brief';
    renderBrief();
    save();
  });

  /* ---------- klavye ---------- */
  document.addEventListener('keydown', (e) => {
    if (!s || s.screen !== 'game') return;
    const n = Number(e.key);
    if (n >= 1 && n <= 4) {
      const btn = document.querySelector(`#choices .choice[data-i="${n - 1}"]`);
      if (btn && !btn.disabled) btn.click();
    }
  });

  /* ---------- başlat ---------- */
  function boot() {
    initTears();
    s = loadSave() || newState();
    if (s.screen === 'title') refreshTitle();
    else refreshTitle(); // devam kartı görünsün diye başlıktan başla
    updateHUD();
    save();
  }

  boot();
})();

